"""Presentation metadata observed on profiles; never generated by a model."""
import re
from urllib.parse import urlsplit

from .core import ReviewError, public_url


def validate_presentation(person):
    if "photo_url" in person and person["photo_url"] is not None:
        person["photo_url"] = public_url(person["photo_url"])
    links = person.get("contact_links", {})
    if not isinstance(links, dict) or set(links) - {"email", "linkedin", "x"}:
        raise ReviewError("Contact links may contain only email, linkedin, and x")
    for kind, value in links.items():
        if kind == "email":
            if not isinstance(value, str) or not re.fullmatch(r"[^\s<>?&#:]+@[^\s<>?&#:]+\.[^\s<>?&#:]+", value):
                raise ReviewError("Use an explicitly published email address")
        else:
            links[kind] = public_url(value)
            host = urlsplit(links[kind]).hostname.lower().removeprefix("www.")
            if host not in ({"linkedin.com"} if kind == "linkedin" else {"x.com", "twitter.com"}):
                raise ReviewError("Contact link does not match its service")
    return person


def model_profile(person):
    # Presentation changes should neither reach a model nor trigger paid re-analysis.
    return {k: v for k, v in person.items() if k not in {"photo_url", "contact_links"}}


def presentation(person):
    links = dict(person.get("contact_links", {}))
    for url in person.get("outbound_links", []):
        host = urlsplit(url).hostname.lower().removeprefix("www.")
        if host == "linkedin.com" and urlsplit(url).path.startswith("/in/"):
            links.setdefault("linkedin", url)
        elif host in {"x.com", "twitter.com"}:
            links.setdefault("x", url)
    return {"photo_url": person.get("photo_url"), "contact_links": links}
